/**
 * =============================================================================
 * BACKTEST TEST UTILITIES
 * =============================================================================
 *
 * Helpers for fixture-grounded unit tests.
 *
 * ## Usage
 * - `loadFixtureFirst15m("2025-10-03")`
 * - `runStrategy("strategy12.10.1", fixture, { triggerPts: 10, profitTargetPts: 36, stopLossPts: 7 })`
 *
 * @module src/lib/backtest/__tests__/testUtils
 */

// =============================================================================
// CONFIGURATION
// =============================================================================

import { readFileSync } from "node:fs";
import { join } from "node:path";
import { generateAlgoTrades, type AlgoTradeRow, type Candle } from "../..";

export type First15mFixture = {
  date: string;
  startPrice: number;
  candles: Candle[];
};

const FIXTURES_DIR = join(
  process.cwd(),
  "src",
  "lib",
  "backtest",
  "__fixtures__",
  "first-15m"
);

const DEFAULT_PARAMS = {
  triggerPts: 10,
  profitTargetPts: 36,
  stopLossPts: 7,
  maxRoundTrips: 3,
  cutoffTime: "09:45",
} as const;

// =============================================================================
// MAIN / EXPORTED
// =============================================================================

/**
 * Load a first-15m fixture from disk.
 *
 * @param date - YYYY-MM-DD
 * @returns Parsed fixture
 */
export function loadFixtureFirst15m(date: string): First15mFixture {
  const fullPath = join(FIXTURES_DIR, `${date}.first15m.json`);
  const raw = JSON.parse(readFileSync(fullPath, "utf-8")) as First15mFixture;

  if (!raw || !raw.date || !raw.startPrice || !Array.isArray(raw.candles)) {
    throw new Error(`Invalid first-15m fixture: ${fullPath}`);
  }

  return raw;
}

/**
 * Run any registered strategy against a first-15m fixture.
 *
 * @param strategyId - Strategy registry ID
 * @param fixture - Fixture data
 * @param params - Backtest params override
 * @returns Algo trade rows
 */
export function runStrategy(
  strategyId: string,
  fixture: First15mFixture,
  params?: Partial<{
    triggerPts: number;
    profitTargetPts: number;
    stopLossPts: number;
    maxRoundTrips: number;
    cutoffTime: string;
    stopLossByProfitThreshold: Record<string, number>;
    atrParams: { period: number; multiplier: number };
    strategyParams: Record<string, unknown>;
  }>
): AlgoTradeRow[] {
  const merged = {
    ...DEFAULT_PARAMS,
    ...params,
  };

  return generateAlgoTrades(
    fixture.candles,
    fixture.startPrice,
    merged.triggerPts,
    merged.profitTargetPts,
    merged.stopLossPts,
    merged.maxRoundTrips,
    false,
    strategyId,
    merged.cutoffTime,
    merged.stopLossByProfitThreshold,
    merged.atrParams,
    merged.strategyParams
  );
}

/**
 * Assert basic invariants about trade rows.
 *
 * Invariants are intentionally non-brittle (do not assert exact PnL).
 */
export function assertRowsWellFormed(rows: AlgoTradeRow[]): void {
  // Must be Open/Close pairs
  if (rows.length % 2 !== 0) {
    throw new Error(`Expected even number of rows (open/close pairs). Got: ${rows.length}`);
  }

  // Close rows must have net defined
  const closeRows = rows.filter((r) => r.id.startsWith("close"));
  for (const r of closeRows) {
    if (r.net === undefined) {
      throw new Error(`Close row missing net: ${r.id} (${r.timestamp})`);
    }
  }

  // Timestamp monotonic (non-decreasing)
  for (let i = 1; i < rows.length; i++) {
    const prev = Date.parse(rows[i - 1].timestamp);
    const cur = Date.parse(rows[i].timestamp);
    if (Number.isFinite(prev) && Number.isFinite(cur) && cur < prev) {
      throw new Error(`Timestamps not monotonic at index ${i}: ${rows[i - 1].timestamp} -> ${rows[i].timestamp}`);
    }
  }
}

/**
 * Summarize rows for debugging output.
 */
export function summarize(rows: AlgoTradeRow[]): {
  trades: number;
  netSum: number;
  firstTimestamp?: string;
  lastTimestamp?: string;
} {
  const closeRows = rows.filter((r) => r.id.startsWith("close"));
  const netSum = closeRows.reduce((sum, r) => sum + (r.net ?? 0), 0);
  return {
    trades: closeRows.length,
    netSum,
    firstTimestamp: rows[0]?.timestamp,
    lastTimestamp: rows[rows.length - 1]?.timestamp,
  };
}

// =============================================================================
// HELPER FUNCTIONS
// =============================================================================

