/**
 * =============================================================================
 * SMOKE TESTS: ORB Retest Breakout (orb-retest-breakout)
 * =============================================================================
 *
 * Invariant-based tests over first-15m real-data fixtures.
 */

import { describe, it, expect } from "vitest";
import {
  assertRowsWellFormed,
  loadFixtureFirst15m,
  runStrategy,
} from "../../__tests__/testUtils";

function hhmm(timestamp: string): string {
  // Supports ISO timestamps like 2025-10-03T09:30:00-04:00
  const m = timestamp.match(/T(\d{2}):(\d{2})/);
  if (m) return `${m[1]}:${m[2]}`;
  const m2 = timestamp.match(/(\d{2}):(\d{2})/);
  if (m2) return `${m2[1]}:${m2[2]}`;
  return "00:00";
}

describe("ORB-R Smoke Tests", () => {
  describe("Layer A — shape + determinism", () => {
    it("does not throw and rows are well formed on a real fixture", () => {
      const fixture = loadFixtureFirst15m("2025-10-03");
      const rows = runStrategy("orb-retest-breakout", fixture, {
        triggerPts: 10,
        profitTargetPts: 36,
        stopLossPts: 7,
        maxRoundTrips: 2,
        cutoffTime: "09:45",
        strategyParams: {
          orbWindowMinutes: 5,
          breakoutBufferAtr: 0.25,
          confirmationMode: "close",
          requireRetest: false,
          retestTimeoutMinutes: 5,
          avoidFirstMinutes: 0,
        },
      });

      expect(Array.isArray(rows)).toBe(true);
      assertRowsWellFormed(rows);
    });
  });

  describe("Layer B — 15m fixture behavior", () => {
    it("does not open new trades after cutoffTime", () => {
      const fixture = loadFixtureFirst15m("2025-12-03");
      const cutoffTime = "09:40";

      const rows = runStrategy("orb-retest-breakout", fixture, {
        triggerPts: 10,
        profitTargetPts: 36,
        stopLossPts: 7,
        maxRoundTrips: 3,
        cutoffTime,
        strategyParams: { orbWindowMinutes: 5, breakoutBufferAtr: 0.25 },
      });

      const openRows = rows.filter((r) => r.id.startsWith("open"));
      for (const r of openRows) {
        expect(hhmm(r.timestamp) <= cutoffTime).toBe(true);
      }
    });
  });

  describe("Layer C — strict correctness contract (red tests)", () => {
    it.fails(
      "RED: orbWindowMinutes must be true minutes (1s candles) — no entry before +5m",
      () => {
        // Construct a deterministic 1-second candle series.
        // Correct behavior: ORB window of 5 minutes means scanning begins after 300 seconds.
        // Current behavior (bug): treats minutes as candles, so scanning begins after 5 seconds.
        const startPrice = 100;
        const candles = Array.from({ length: 320 }, (_, i) => {
          const sec = i.toString().padStart(2, "0");
          const time = `2025-01-02T09:30:${sec}-05:00`;
          // Flat baseline
          let open = 100;
          let high = 100;
          let low = 100;
          let close = 100;

          // After 6 seconds, produce a breakout and trigger soon after
          if (i === 6) {
            high = 110;
            close = 110;
          }
          if (i === 7) {
            high = 102;
            close = 102;
          }

          return { time, open, high, low, close, volume: 100 };
        });

        const fixture = { date: "2025-01-02", startPrice, candles };
        const rows = runStrategy("orb-retest-breakout", fixture, {
          triggerPts: 1,
          profitTargetPts: 50,
          stopLossPts: 10,
          maxRoundTrips: 1,
          cutoffTime: "09:45",
          strategyParams: {
            orbWindowMinutes: 5,
            breakoutBufferAtr: 0,
          },
        });

        const openRows = rows.filter((r) => r.id.startsWith("open"));
        // Strict contract: there should be no entries before 09:35 when orbWindowMinutes=5.
        for (const r of openRows) {
          expect(hhmm(r.timestamp) >= "09:35").toBe(true);
        }
      }
    );
  });
});

