  const m2 = timestamp.match(/(\d{2}):(\d{2})/);
  if (m2) return `${m2[1]}:${m2[2]}`;
  return "00:00";
}

describe("VWAP-Fade Smoke Tests", () => {
  describe("Layer A — shape + determinism", () => {
    it("does not throw and rows are well formed on a real fixture", () => {
      const fixture = loadFixtureFirst15m("2025-10-17");
      const rows = runStrategy("vwap-deviation-fade", fixture, {
        triggerPts: 10,
        profitTargetPts: 36,
        stopLossPts: 7,
        maxRoundTrips: 2,
        cutoffTime: "09:45",
        strategyParams: {
          deviationAtr: 1.0,
          confirmationMode: "close_back_inside",
          stopAtrMult: 1.0,
          avoidFirstMinutes: 0,
        },
      });

      expect(Array.isArray(rows)).toBe(true);
      assertRowsWellFormed(rows);
    });
  });

  describe("Layer B — 15m fixture behavior", () => {
    it("does not open new trades after cutoffTime", () => {
      const fixture = loadFixtureFirst15m("2025-12-03");
      const cutoffTime = "09:40";

      const rows = runStrategy("vwap-deviation-fade", fixture, {
        triggerPts: 10,
        profitTargetPts: 36,
        stopLossPts: 7,
        maxRoundTrips: 3,
        cutoffTime,
        strategyParams: {
          deviationAtr: 1.0,
          confirmationMode: "close_back_inside",
          stopAtrMult: 1.0,
          avoidFirstMinutes: 0,
        },
      });

      const openRows = rows.filter((r) => r.id.startsWith("open"));
      for (const r of openRows) {
        expect(hhmm(r.timestamp) <= cutoffTime).toBe(true);
      }
    });
  });

  describe("Layer C — strict correctness contract (red tests)", () => {
    it.fails("RED: VWAP must be deterministic even when volume is 0", () => {
      // Desired behavior: if volume is 0, VWAP should still be computable via an explicit policy
      // (e.g. equal weighting or skipping with a documented/observable reason).
      // Current behavior: VWAP can become undefined and the strategy silently continues.
      const startPrice = 100;
      const candles = [
        {
          time: "2025-01-02T09:30:00-05:00",
          open: 100,
          high: 100,
          low: 100,
          close: 100,
          volume: 0,
        },
        {
          time: "2025-01-02T09:30:01-05:00",
          open: 50,
          high: 50,
          low: 50,
          close: 50,
          volume: 0,
        },
        {
          time: "2025-01-02T09:30:02-05:00",
          open: 70,
          high: 70,
          low: 70,
          close: 70,
          volume: 0,
        },
      ];

      const fixture = { date: "2025-01-02", startPrice, candles };
      const rows = runStrategy("vwap-deviation-fade", fixture, {
        triggerPts: 1,
        profitTargetPts: 50,
        stopLossPts: 10,
        maxRoundTrips: 1,
        cutoffTime: "09:45",
        atrParams: { period: 1, multiplier: 1 },
        strategyParams: {
          deviationAtr: 1.0,
          confirmationMode: "close_back_inside",
          stopAtrMult: 1.0,
          avoidFirstMinutes: 0,
        },
      });

      // Strict contract: the deviation should be detectable even with volume=0.
      // Expect at least one trade if VWAP is computed deterministically.
      expect(rows.length).toBeGreaterThan(0);
    });
  });
});

/**
 * =============================================================================
 * SMOKE TESTS: ATR Trailing Stop Loss (atr-trailing-sldrag)
 * =============================================================================
 *
 * Invariant-based tests over first-15m real-data fixtures.
 */

import { describe, it, expect } from "vitest";
import {
  assertRowsWellFormed,
  loadFixtureFirst15m,
  runStrategy,
} from "../../__tests__/testUtils";

describe("ATR-Trailing Smoke Tests", () => {
  describe("Layer A — shape + determinism", () => {
    it("does not throw and rows are well formed on a real fixture", () => {
      const fixture = loadFixtureFirst15m("2025-10-10");
      const rows = runStrategy("atr-trailing-sldrag", fixture, {
        triggerPts: 10,
        profitTargetPts: 36,
        stopLossPts: 7,
        maxRoundTrips: 2,
        cutoffTime: "09:45",
        atrParams: { period: 14, multiplier: 2.0 },
      });

      expect(Array.isArray(rows)).toBe(true);
      assertRowsWellFormed(rows);
    });
  });

  describe("Layer B — 15m fixture behavior", () => {
    it("does not open new trades after cutoffTime", () => {
      const fixture = loadFixtureFirst15m("2025-10-17");
      const cutoffTime = "09:40";

      const rows = runStrategy("atr-trailing-sldrag", fixture, {
        triggerPts: 10,
        profitTargetPts: 36,
        stopLossPts: 7,
        maxRoundTrips: 3,
        cutoffTime,
        atrParams: { period: 14, multiplier: 2.0 },
      });

      const openRows = rows.filter((r) => r.id.startsWith("open"));
      for (const r of openRows) {
        const m = r.timestamp.match(/T(\d{2}):(\d{2})/);
        const t = m ? `${m[1]}:${m[2]}` : "00:00";
        expect(t <= cutoffTime).toBe(true);
      }
    });
  });

  describe("Layer C — strict correctness contract (red tests)", () => {
    it.fails("RED: trailing stop updates should apply next candle (no same-bar tightening)", () => {
      // Desired sequencing model (Ticket 2.5): stop updates apply starting next candle.
      // Current behavior tightens the trailing stop using the current candle's high/low,
      // then checks for SL hit in the same candle.
      const startPrice = 100;
      const candles = [
        {
          time: "2025-01-02T09:30:00-05:00",
          open: 100,
          high: 102,
          low: 100,
          close: 102,
          volume: 100,
        },
        {
          time: "2025-01-02T09:30:01-05:00",
          open: 102,
          high: 120,
          low: 110,
          close: 115,
          volume: 100,
        },
        {
          time: "2025-01-02T09:30:02-05:00",
          open: 115,
          high: 116,
          low: 114,
          close: 115,
          volume: 100,
        },
      ];

      const fixture = { date: "2025-01-02", startPrice, candles };
      const rows = runStrategy("atr-trailing-sldrag", fixture, {
        triggerPts: 1,
        profitTargetPts: 1000, // ensure TP never hits
        stopLossPts: 10,
        maxRoundTrips: 1,
        cutoffTime: "09:45",
        atrParams: { period: 1, multiplier: 1 },
      });

      const close = rows.find((r) => r.id.startsWith("close"));
      expect(close).toBeDefined();
      // Under apply-next-candle sequencing, this should not be an SL hit on candle[1].
      expect(close?.note).toBe("EOD Push");
    });
  });
});

